mapper.select:
select
te.Te_Name as teName,
te.Te_Code as teCode,
te.Te_Type as teType,
te.Te_Charge_Type as teChargeType,
te.Te_Expiration_Time as teExpirationTime,
mn.*
from SYS_Tenant_Pay mn
left join SYS_Tenant te on te.Te_Id=mn.Te_Id

    
        and te.Te_Type=#{params.teType}
    
    
        and mn.State=#{params.state}
    
    
        and mn.Pay_Type=#{params.payType}
    
    
        and mn.Pay_Way=#{params.payWay}
    
    
        and mn.Pay_Status=#{params.payStatus}
    
    
        and te.Te_Charge_Type=#{params.teChargeType}
    
    
        and INSTR(mn.Create_Uname,#{params.createUname})
    
    
        and INSTR(te.Te_Name,#{params.teName})
    
    
        and INSTR(te.Te_Code,#{params.teCode})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
